const assetUI={tab:'dashboard',search:'',trackingMode:'',category:'',location:'',status:'',historyAssetId:'',maintenanceAssetId:'',maintenanceSearch:'',quantityAssetId:''};

function amClone(x){return JSON.parse(JSON.stringify(x))}
function amObj(x){return x&&typeof x==='object'&&!Array.isArray(x)?x:{}}
function amArr(x){return Array.isArray(x)?x:[]}
function amNum(v){const raw=String(v??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[٬,،\s]/g,'').replace(/[^0-9.\-]/g,'');const n=Number(raw);return Number.isFinite(n)?n:0}
function amText(v){return String(v??'').trim()}
