function amEsc(v){return typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function amNow(){return new Date().toISOString()}
function amToday(){return typeof todayJ==='function'?todayJ():''}
function amMonth(date){return /^\d{4}\/\d{2}\/\d{2}$/.test(date||'')?date.slice(0,7):''}
function amUid(prefix,rows,digits=4){let max=0;amArr(rows).forEach(x=>{const m=String(x.id||'').match(/(\d+)$/);if(m)max=Math.max(max,+m[1])});return `${prefix}-${String(max+1).padStart(digits,'0')}`}
